package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static ge.opensoft.openservice.WorkflowSupport.*;
import static ge.opensoft.openservice.EmployeeCasesAcceptance.result;
import static org.junit.jupiter.api.Assertions.*;
import java.util.*;
import java.util.concurrent.*;

final class OffboardingAcceptance {
 static String api(String source){return "/api/openservice/users/"+source+"/offboarding";}
 static String ui(String source){return "/admin/accounts/"+source+"/offboarding";}
 static Map<String,Object> seed(Store store,String prefix)throws Exception {
  String table=ReportFormsAcceptance.seed(store),from=prefix+"Departing",to=prefix+"Successor";try(var db=store.open()){String admin=PlatformFoundationTest.bind(db);for(String name:List.of(from,to))Service.createAccount(db,map("name",name,"role",name.equals(from)?"admin":"agent","password",PASSWORD));String source=RecordAccess.owner(db,from),target=RecordAccess.owner(db,to),group=Service.create(db,"sys_user_group",map("short_description","Continuing service team"),"admin").get("sys_id").toString();for(String id:List.of(source,target))db.update("INSERT INTO os_group_member(group_id,user_id) VALUES(?,?)",group,id);
   var record=Service.create(db,"incident",map("short_description","Supported departing assignment","assigned_to",from,"assignment_group",group),"admin");String id=record.get("sys_id").toString();WorkTasks.command(db,"incident",id,map("operation","configure","revision",0,"record_revision",0,"close_at","6"));var page=WorkTasks.command(db,"incident",id,map("operation","create","revision",1,"record_revision",1,"summary","Continue departed employee work","details","Verify service restoration","group_id",group,"required",true,"predecessors",List.of()));String task=objects(page.get("tasks")).getFirst().get("task_id").toString();
   var closed=Service.create(db,"incident",map("short_description","Historical completed assignment","assigned_to",from),"admin");for(String state:List.of("2","6","7"))Service.update(db,"incident",closed,map("state",state),"admin","admin",null);
   String request=Service.create(db,"sc_request",map("short_description","Continue routed fulfilment"),"admin").get("sys_id").toString();db.update("INSERT INTO os_fulfilment(request_id,group_id,assignee_id,state,outcome,revision,updated_at) VALUES(?,?,'','queued','',1,?)",request,group,now());var privateRecord=db.one("SELECT * FROM os_record WHERE \"table\"=? ORDER BY seq DESC LIMIT 1",table);RecordAccess.change(db,privateRecord,admin,map("visibility","private","owner_id",source));
   db.viewerId=source;db.viewerRole="admin";WorkTasks.command(db,"incident",id,map("operation","claim","revision",0,"record_revision",2,"task_id",task));Fulfilment.control(db,request,map("operation","claim","revision",1,"request_revision",0));String report=SavedReports.save(db,source,map("name","Departing private report","table",table,"query",map("field","amount"),"shared",false)).get("report_id").toString();ReportMeasurements.capture(db,report,map("key",Values.id()));assertEquals("100",object(ReportMeasurements.context(db,report).get("current")).get("sum"));PlatformFoundationTest.bind(db);Service.changeRole(db,admin,source,map("role","agent"));db.connection.commit();return map("source",source,"target",target,"from",from,"to",to,"group",group,"record",id,"task",task,"request",request,"report",report,"table",table,"closed",closed.get("sys_id"));}
 }
 static Map<String,Object> preview(WorkflowSupport h,Map<String,Object> fixture)throws Exception {return object(result(h.get(api(fixture.get("source").toString())+"?recipient="+fixture.get("to"),auth("admin"))).get("preview"));}
 static Map<String,Object> body(Map<String,Object> preview){return map("recipient",object(preview.get("recipient")).get("name"),"review",preview.get("review"),"reason","Reviewed departure and continuity plan <script>");}
 static void run(WorkflowSupport h)throws Exception {
  var f=seed(h.store,"Handoff");String source=f.get("source").toString(),target=f.get("target").toString();h.login(f.get("from").toString());var before=preview(h,f);assertEquals(1,objects(before.get("records")).size());assertEquals(1,objects(before.get("tasks")).size());assertEquals(1,objects(before.get("fulfilment")).size());assertEquals(1,objects(before.get("reports")).size());assertEquals(before.get("review"),preview(h,f).get("review"));var receipt=result(h.json("POST",api(source),body(before),auth("admin")));assertNotNull(receipt.get("handoff_id"));assertEquals(302,h.get("/account",null).statusCode());assertEquals(401,h.get("/api/now/table/incident",auth(f.get("from").toString())).statusCode());assertEquals(409,h.json("POST",api(source),body(before),auth("admin")).statusCode());
  try(var db=h.store.open()){PlatformFoundationTest.bind(db);assertEquals(0,((Number)Offboarding.account(db,source).get("active")).intValue());assertEquals(f.get("to"),object(Service.readRecord(db,"incident",f.get("record").toString()).get("data")).get("assigned_to"));assertEquals(f.get("from"),object(Service.readRecord(db,"incident",f.get("closed").toString()).get("data")).get("assigned_to"));assertEquals("queued",db.one("SELECT state FROM os_case_task WHERE task_id=?",f.get("task")).get("state"));assertEquals("queued",db.one("SELECT state FROM os_fulfilment WHERE request_id=?",f.get("request")).get("state"));assertEquals(target,db.one("SELECT owner_id FROM os_saved_report WHERE report_id=?",f.get("report")).get("owner_id"));assertEquals(source,db.one("SELECT viewer_id FROM os_report_measurement WHERE report_id=?",f.get("report")).get("viewer_id"));assertEquals(1,db.count("SELECT COUNT(*) FROM os_offboarding"));}
  var current=WorkTasksAcceptance.command(h,f.get("record").toString(),"claim",f.get("task").toString());WorkTasksAcceptance.send(h,f.get("record").toString(),current,f.get("to").toString());WorkTasksAcceptance.act(h,f.get("record").toString(),f.get("task").toString(),"complete",f.get("to").toString(),"Verified continued work");var routed=FulfilmentAcceptance.get(h,f.get("request").toString(),f.get("to").toString());result(h.json("POST",FulfilmentAcceptance.path(f.get("request").toString()),FulfilmentAcceptance.command(routed,"claim"),auth(f.get("to").toString())));assertEquals(403,h.get(ReportMeasurementsAcceptance.path(f.get("report").toString()),auth(f.get("to").toString())).statusCode());assertTrue(html(h.get("/reports/"+f.get("report"),auth(f.get("to").toString()))).contains(">10<"));new Store(h.environment);assertEquals(1,objects(result(h.get(api(source),auth("admin"))).get("history")).size());assertTrue(html(h.get(ui(source),auth("admin"))).contains("&lt;script&gt;"));
 }
 static void configuration(WorkflowSupport h)throws Exception {
  var f=seed(h.store,"Config");String source=f.get("source").toString(),path=api(source);assertEquals(401,h.get(path,null).statusCode());assertEquals(403,h.get(path,auth(f.get("to").toString())).statusCode());assertEquals(200,h.get(path,auth("admin")).statusCode());assertEquals(405,h.json("PUT",path,map(),auth("admin")).statusCode());assertEquals(400,h.get(path+"?extra=1",auth("admin")).statusCode());assertEquals(400,h.get(path+"?recipient=a&recipient=b",auth("admin")).statusCode());assertEquals(400,h.get(path+"?recipient="+"x".repeat(81),auth("admin")).statusCode());assertEquals(404,h.get(api(id()),auth("admin")).statusCode());assertEquals(400,h.get(path+"?recipient="+f.get("from"),auth("admin")).statusCode());for(String invalid:List.of("Missing","")){if(!invalid.isEmpty())assertEquals(400,h.get(path+"?recipient="+invalid,auth("admin")).statusCode());}h.account("HandoffReader","reader");assertEquals(400,h.get(path+"?recipient=HandoffReader",auth("admin")).statusCode());String admin;try(var db=h.store.open()){admin=RecordAccess.owner(db,"admin");}assertEquals(400,h.get(api(admin),auth("admin")).statusCode());
  var input=body(preview(h,f));for(var bad:List.of(map(),map("recipient",f.get("to"),"review","bad","reason","why"),map("recipient",f.get("to"),"review",input.get("review"),"reason",""))){assertEquals(400,h.json("POST",path,bad,auth("admin")).statusCode());}assertEquals(400,h.json("POST",path+"?recipient=x",input,auth("admin")).statusCode());assertEquals(403,h.form(ui(source),input,auth("admin")).statusCode());
  try(var db=h.store.open()){for(String column:List.of("active","api_only","password_reset_required")){int before=((Number)Offboarding.account(db,f.get("target").toString()).get(column)).intValue();db.update("UPDATE os_user SET "+column+"=? WHERE user_id=?",column.equals("active")?0:1,f.get("target"));assertEquals(400,assertThrows(Failure.class,()->{PlatformFoundationTest.bind(db);Offboarding.preview(db,source,f.get("to").toString());}).status);db.update("UPDATE os_user SET "+column+"=? WHERE user_id=?",before,f.get("target"));}}
 }
 static void teamAuthority(WorkflowSupport h)throws Exception {
  var f=seed(h.store,"Team");try(var db=h.store.open()){PlatformFoundationTest.bind(db);Service.update(db,"incident",Service.record(db,"incident",f.get("record").toString()),map("assigned_to",""),"admin","admin",null);db.update("DELETE FROM os_group_member WHERE user_id=?",f.get("target"));db.connection.commit();}assertEquals(403,h.get(api(f.get("source").toString())+"?recipient="+f.get("to"),auth("admin")).statusCode(),"Successor cannot continue work without current team membership");
 }
 static void authority(WorkflowSupport h)throws Exception {
  var f=seed(h.store,"Authority");String path=api(f.get("source").toString())+"?recipient="+f.get("to");var reviewed=body(preview(h,f));FulfilmentAcceptance.member(h,f.get("group").toString(),f.get("to").toString(),false);assertEquals(403,h.get(path,auth("admin")).statusCode());assertEquals(403,h.json("POST",api(f.get("source").toString()),reviewed,auth("admin")).statusCode());FulfilmentAcceptance.member(h,f.get("group").toString(),f.get("to").toString(),true);ProblemInvestigationsAcceptance.access(h,"incident",f.get("record").toString(),"private",f.get("source").toString());assertEquals(404,h.get(path,auth("admin")).statusCode());ProblemInvestigationsAcceptance.access(h,"incident",f.get("record").toString(),"workspace","");
  Map<String,Object> original;try(var db=h.store.open()){original=Service.schema(db,"incident");}for(String field:List.of("assigned_to","state","description")){var changed=new LinkedHashMap<>(original);changed.put("field_rules",map(field,map("type","string","read_roles",List.of("admin"))));ReferencePickerAcceptance.writeSchema(h,"incident",changed);try{assertEquals(403,h.get(path,auth("admin")).statusCode());}finally{ReferencePickerAcceptance.writeSchema(h,"incident",original);}}
  try(var db=h.store.open()){PlatformFoundationTest.bind(db);String other=Service.create(db,"sys_user_group",map("short_description","Different continuing team"),"admin").get("sys_id").toString();db.update("UPDATE os_fulfilment SET group_id=? WHERE request_id=?",other,f.get("request"));db.connection.commit();}assertEquals(403,h.get(path,auth("admin")).statusCode());assertEquals(200,h.get(api(f.get("source").toString())+"?recipient=admin",auth("admin")).statusCode());
  try(var db=h.store.open()){String actor=PlatformFoundationTest.bind(db);var schema=Service.schema(db,f.get("table").toString());object(schema.get("field_rules")).put("amount",map("type","decimal","read_roles",List.of("admin")));db.update("UPDATE os_schema SET definition="+db.jsonParameter()+" WHERE name=?",JSON.writeValueAsString(schema),f.get("table"));db.update("UPDATE os_fulfilment SET group_id=? WHERE request_id=?",f.get("group"),f.get("request"));assertEquals(400,assertThrows(Failure.class,()->Offboarding.preview(db,f.get("source").toString(),f.get("to").toString())).status);assertEquals(actor,db.viewerId);assertEquals("admin",db.viewerRole);}
 }
 static void stale(WorkflowSupport h)throws Exception {
  var f=seed(h.store,"Stale");String path=api(f.get("source").toString());var input=body(preview(h,f));assertEquals(200,h.json("PATCH","/api/now/table/incident/"+f.get("record"),map("description","Changed after review"),auth("admin")).statusCode());assertEquals(409,h.json("POST",path,input,auth("admin")).statusCode());input=body(preview(h,f));try(var db=h.store.open()){PlatformFoundationTest.bind(db);Service.create(db,"incident",map("short_description","Newly assigned after review","assigned_to",f.get("from")),"admin");db.connection.commit();}assertEquals(409,h.json("POST",path,input,auth("admin")).statusCode());input=body(preview(h,f));try(var db=h.store.open()){db.update("UPDATE os_saved_report SET name='Edited after review' WHERE report_id=?",f.get("report"));db.connection.commit();}assertEquals(409,h.json("POST",path,input,auth("admin")).statusCode());for(String field:List.of("source","target")){input=body(preview(h,f));try(var db=h.store.open()){db.update("UPDATE os_user SET auth_revision=auth_revision+1 WHERE user_id=?",f.get(field));db.connection.commit();}assertEquals(409,h.json("POST",path,input,auth("admin")).statusCode());}assertEquals(200,h.json("POST",path,body(preview(h,f)),auth("admin")).statusCode());
 }
 static void fieldBlocker(WorkflowSupport h)throws Exception {
  var f=seed(h.store,"Field");String source=f.get("source").toString();try(var db=h.store.open()){db.update("INSERT INTO os_field_dispatch(task_id,technician_id,starts,ends,location,status,reason,revision) VALUES(?,?,?,?,?,'accepted','',1)",f.get("task"),source,System.currentTimeMillis(),System.currentTimeMillis()+600000,"Customer site");db.connection.commit();}var plan=preview(h,f);assertEquals(1,objects(plan.get("dispatches")).size());assertEquals(409,h.json("POST",api(source),body(plan),auth("admin")).statusCode());assertTrue(html(h.get(ui(source)+"?recipient="+f.get("to"),auth("admin"))).contains("Field work blocks this handoff"));try(var db=h.store.open()){PlatformFoundationTest.bind(db);String record=f.get("record").toString();FieldDispatch.command(db,"incident",record,f.get("task").toString(),map("operation","release","revision",1,"task_revision",1,"record_revision",Service.record(db,"incident",record).get("revision"),"reason","Reviewed technician departure"));db.connection.commit();}assertEquals(200,h.json("POST",api(source),body(preview(h,f)),auth("admin")).statusCode());
 }
 static void atomic(WorkflowSupport h)throws Exception {
  var f=seed(h.store,"Atomic");String extra;Map<String,Object> original;try(var db=h.store.open()){PlatformFoundationTest.bind(db);var record=Service.create(db,"incident",map("short_description","Must roll back reassignment","assigned_to",f.get("from")),"admin");Service.update(db,"incident",record,map("state","2"),"admin","admin",null);extra=record.get("sys_id").toString();original=Service.schema(db,"incident");var changed=object(JSON.readValue(JSON.writeValueAsString(original),Map.class));object(changed.get("flow")).put("1",List.of());db.update("UPDATE os_schema SET definition="+db.jsonParameter()+" WHERE name='incident'",JSON.writeValueAsString(changed));db.connection.commit();}try{assertEquals(409,h.json("POST",api(f.get("source").toString()),body(preview(h,f)),auth("admin")).statusCode());try(var db=h.store.open()){PlatformFoundationTest.bind(db);assertEquals(f.get("from"),object(Service.readRecord(db,"incident",extra).get("data")).get("assigned_to"));assertEquals(f.get("source"),db.one("SELECT owner_id FROM os_saved_report WHERE report_id=?",f.get("report")).get("owner_id"));assertEquals(1,((Number)Offboarding.account(db,f.get("source").toString()).get("active")).intValue());assertEquals(0,db.count("SELECT COUNT(*) FROM os_offboarding"));}}finally{ReferencePickerAcceptance.writeSchema(h,"incident",original);}
 }
 static void limits(WorkflowSupport h)throws Exception {
  var f=seed(h.store,"Limits");String path=api(f.get("source").toString())+"?recipient="+f.get("to");try(var db=h.store.open()){for(int n=0;n<100;n++)db.update("INSERT INTO os_saved_report(report_id,owner_id,name,table_name,definition,shared) SELECT ?,owner_id,name,table_name,definition,shared FROM os_saved_report WHERE report_id=?",id(),f.get("report"));db.connection.commit();}assertEquals(400,h.get(path,auth("admin")).statusCode());try(var db=h.store.open()){db.update("DELETE FROM os_saved_report WHERE report_id<>?",f.get("report"));for(int n=0;n<100;n++)db.update("INSERT INTO os_saved_report(report_id,owner_id,name,table_name,definition,shared) SELECT ?,?,name,table_name,definition,shared FROM os_saved_report WHERE report_id=?",id(),f.get("target"),f.get("report"));db.connection.commit();}assertEquals(400,h.get(path,auth("admin")).statusCode());try(var db=h.store.open()){db.update("DELETE FROM os_saved_report WHERE owner_id=?",f.get("target"));for(int n=0;n<1000;n++)db.update("INSERT INTO os_record(sys_id,\"table\",data,original,created,updated,creator,updater,revision) SELECT ?,\"table\",data,original,created,updated,creator,updater,revision FROM os_record WHERE sys_id=?",id(),f.get("record"));db.connection.commit();}assertEquals(400,h.get(path,auth("admin")).statusCode());
 }
 static void concurrency(WorkflowSupport h)throws Exception {
  var f=seed(h.store,"Concurrent");String path=api(f.get("source").toString());var body=body(preview(h,f));var start=new CountDownLatch(1);try(var pool=Executors.newFixedThreadPool(2)){var results=new ArrayList<Future<Integer>>();for(int n=0;n<2;n++)results.add(pool.submit(()->{start.await();return h.json("POST",path,body,auth("admin")).statusCode();}));start.countDown();var actual=new ArrayList<Integer>();for(var future:results)actual.add(future.get(20,TimeUnit.SECONDS));Collections.sort(actual);assertEquals(List.of(200,409),actual);}try(var db=h.store.open()){assertEquals(1,db.count("SELECT COUNT(*) FROM os_offboarding"));}
 }
 static void edges(WorkflowSupport h)throws Exception {
  var f=seed(h.store,"Edges");String source=f.get("source").toString();try(var db=h.store.open()){PlatformFoundationTest.bind(db);Service.changeActive(db,db.viewerId,source,map("active",false));db.connection.commit();}assertEquals(200,h.json("POST",api(source),body(preview(h,f)),auth("admin")).statusCode());assertEquals(409,h.json("POST",api(source),body(preview(h,f)),auth("admin")).statusCode());try(var db=h.store.open()){PlatformFoundationTest.bind(db);Service.changeActive(db,db.viewerId,source,map("active",true));for(int n=1;n<100;n++)db.update("INSERT INTO os_offboarding(handoff_id,source_id,recipient_id,actor_id,created_at,detail) SELECT ?,source_id,recipient_id,actor_id,created_at,detail FROM os_offboarding WHERE source_id=? LIMIT 1",id(),source);db.connection.commit();}assertEquals(400,h.json("POST",api(source),body(preview(h,f)),auth("admin")).statusCode());
  try(var db=h.store.open()){PlatformFoundationTest.bind(db);db.update("DELETE FROM os_offboarding WHERE source_id=?",source);db.update("UPDATE os_user SET role='admin',api_only=0 WHERE user_id=?",source);db.update("UPDATE os_user SET api_only=1 WHERE name='admin'");db.connection.commit();}assertEquals(409,h.json("POST",api(source),body(preview(h,f)),auth("admin")).statusCode());try(var db=h.store.open()){db.update("UPDATE os_user SET api_only=0 WHERE name='admin'");db.connection.commit();}
 }
 static void inactiveInventories(WorkflowSupport h)throws Exception {
  for(String category:List.of("tasks","fulfilment","reports")){var f=seed(h.store,"Inactive"+category);String source=f.get("source").toString();try(var db=h.store.open()){PlatformFoundationTest.bind(db);Service.update(db,"incident",Service.record(db,"incident",f.get("record").toString()),map("assigned_to",f.get("to")),"admin","admin",null);if(!category.equals("tasks"))db.update("DELETE FROM os_case_task WHERE task_id=?",f.get("task"));if(!category.equals("fulfilment"))db.update("DELETE FROM os_fulfilment WHERE request_id=?",f.get("request"));if(!category.equals("reports"))db.update("UPDATE os_saved_report SET owner_id=? WHERE report_id=?",f.get("target"),f.get("report"));Service.changeActive(db,db.viewerId,source,map("active",false));db.connection.commit();}assertEquals(200,h.json("POST",api(source),body(preview(h,f)),auth("admin")).statusCode(),category);assertEquals(1,objects(result(h.get(api(source),auth("admin"))).get("history")).size());}
 }
}
